<svg width="240" height="30" viewBox="0 0 240 30" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Route from origin to destination by van" xmlns:c2pa="http://c2pa.org/manifest"><metadata><c2pa:manifest></c2pa:manifest></metadata>
